448	
449	    seg = strtok_r(buf, ";", &save);
450	    while (seg != NULL && n < VMAP_ROUTE_TRIP_MAX_WAYPOINTS) {
451	        char * comma = strchr(seg, ',');
452	
453	        if (!comma) {
454	            return false;
455	        }
456	        *comma = '\0';
457	        out[n].lon = atof(seg);
458	        out[n].lat = atof(comma + 1);
459	        n++;
460	        seg = strtok_r(NULL, ";", &save);
461	    }
462	
463	    if (n == 0) {
464	        return false;
465	    }
466	
467	    *out_count = n;
468	    return true;
