603	 * @param arg "on"|"off"|"toggle"（空 = 开）；"run:<场景名>"|"next"|"prev" 单场景；
604	 *            "mode:<模式名>"|"start:<模式名>" 循环演示（random/linear/minghu/full）。
605	 */
606	static void bicycle_ui_ctl_handle_demo(const char * arg)
607	{
608	    char msg[96];
609	    int rc;
610	
611	    /* 循环演示模式：mode:<名>/start:<名>（NSH `demo start|mode|on <name>`）。
612	     * 名字表在 bicycle_demo.h，未知名字提示后直接返回，别落到末尾的通用 toast。 */
613	    if (arg != NULL && (strncmp(arg, "mode:", 5) == 0 ||
614	                        strncmp(arg, "start:", 6) == 0)) {
615	        const char * name = strchr(arg, ':') + 1;
616	        int mode = bicycle_demo_mode_from_name(name);
617	
618	        if (mode < 0) {
619	            lv_pm_bottom_show("未知演示模式", 0);
620	            return;
621	        }
622	
623	        rc = bicycle_demo_start_mode((bicycle_demo_mode_t)mode);
624	        if (rc != BICYCLE_DEMO_OK) {
625	            lv_pm_bottom_show("演示模式启动失败", 0);
626	            return;
627	        }
628	
629	        snprintf(msg, sizeof(msg), "演示：%s", bicycle_ui_ctl_demo_desc());
630	        lv_pm_bottom_show(msg, 0);
631	        return;
632	    }
633	
634	    /* 单场景：run:<name> 由 demo 表查找；未知名字要提示，不能静默。 */
635	    if (arg != NULL && strncmp(arg, "run:", 4) == 0) {
636	        if (arg[4] == '\0') {
637	            lv_pm_bottom_show("未知演示场景", 0);
638	            return;
639	        }
640	
641	        rc = bicycle_demo_scene_run(arg + 4);
642	        if (rc == 0) {
643	            bicycle_ui_ctl_demo_scene_toast();
644	        } else if (rc == BICYCLE_DEMO_SCENE_ERR_UNKNOWN) {
645	            lv_pm_bottom_show("未知演示场景", 0);
646	        } else {
647	            lv_pm_bottom_show("演示场景启动失败", 0);
648	        }
649	        return;
650	    }
651	
652	    if (arg != NULL && (strcmp(arg, "next") == 0 || strcmp(arg, "prev") == 0)) {
653	        rc = bicycle_demo_scene_step(strcmp(arg, "next") == 0 ? 1 : -1);
654	        if (rc == 0) {
655	            bicycle_ui_ctl_demo_scene_toast();
656	        } else {
657	            lv_pm_bottom_show("演示场景启动失败", 0);
658	        }
659	        return;
660	    }
661	
662	    if (arg != NULL && strcmp(arg, "off") == 0) {
663	        bicycle_demo_stop();
664	        lv_pm_bottom_show("演示模式已停止", 0);
665	        return;
666	    }
667	
668	    if (arg != NULL && strcmp(arg, "toggle") == 0) {
669	        bicycle_demo_toggle();
670	    } else if (!bicycle_demo_active()) {
671	        rc = bicycle_demo_start();
672	
673	        if (rc != BICYCLE_DEMO_OK) {
674	            lv_pm_bottom_show(bicycle_demo_error_text(rc), 0);
675	            return;
676	        }
677	    }
678	
679	    snprintf(msg, sizeof(msg), "演示：%s", bicycle_ui_ctl_demo_desc());
680	    lv_pm_bottom_show(msg, 0);
681	}
