822	        while (myvendor_sys_notif_take(&ntf)) {
823	        }
824	
825	        return;
826	    }
827	
828	    if (lv_pm_notify_is_showing()) {
829	        return;
830	    }
831	
832	    if (!myvendor_sys_notif_take(&ntf)) {
833	        return;
834	    }
835	
836	    /* 防御（板级，2026-09-24）：**弹窗限速 1.5 s**。
837	     *
838	     * 现场：微信**通话**通知是常驻的、手机侧持续下发，UI 每抽到一条就重弹一次
839	     * `lv_pm_notify_show_ex()`（modal 反复 show/hide）⇒ 整块 UI 卡死。
840	     * bridge 侧已做"同键合并 + 弹窗限流"（`companion_bridge_notif_post()`），
841	     * 这里在 UI 侧再兜一道：太密的直接丢弃（该条仍在 inbox 列表里）。 */
842	    {
