844	        uint32_t t = (uint32_t)lv_tick_get();
845	
846	        if (s_last_show_ms != 0u && (uint32_t)(t - s_last_show_ms) < 1500u) {
847	            return;
848	        }
849	
850	        s_last_show_ms = t ? t : 1u;
851	    }
852	
853	    lv_pm_notify_show_ex(ntf.title[0] != '\0' ? ntf.title : "通知",
854	                         ntf.body[0] != '\0' ? ntf.body : ntf.title,
855	                         ntf.icon[0] != '\0' ? ntf.icon : NULL,
856	                         BICYCLE_PHONE_NOTIF_MS);
857	}
