static size_t bicycle_ui_ctl_fit_utf8_width(const char * s, int32_t max_w)
{
    const lv_font_t * font = helm_font_sys(14, helm_font_title());
    size_t n = 0u;
    int32_t w = 0;

    if (s == NULL || font == NULL || max_w <= 0) return 0u;

    while (s[n] != '\0') {
        const unsigned char c = (unsigned char)s[n];
        size_t len;
        size_t i;
        uint32_t cp;
        uint32_t next;

        if (c < 0x80u) { len = 1u; }
        else if ((c & 0xE0u) == 0xC0u) { len = 2u; }
        else if ((c & 0xF0u) == 0xE0u) { len = 3u; }
        else if ((c & 0xF8u) == 0xF0u) { len = 4u; }
        else { break; }

        for (i = 1u; i < len; i++) {
            const unsigned char cc = (unsigned char)s[n + i];
            if (cc == '\0' || (cc & 0xC0u) != 0x80u) return n;
        }

        cp = decode(...);
        next = next codepoint after n+len (or 0)
        w += lv_font_get_glyph_width(font, cp, next);
        if (w > max_w) break;
        n += len;
    }
    return n;
}
```

