```c
/**
 * @brief 取 s[n] 起一个完整 UTF-8 字符的字节数；NUL/非法/续字节不完整返回 0。
 */
static size_t bicycle_ui_ctl_utf8_len(const char * s, size_t n)
{
    const unsigned char c = (unsigned char)s[n];
    size_t len;
    size_t i;

    if (c == '\0') {
        return 0u;
    }
    if (c < 0x80u) {
        return 1u;
    }
    if ((c & 0xE0u) == 0xC0u) {
        len = 2u;
    } else if ((c & 0xF0u) == 0xE0u) {
        len = 3u;
    } else if ((c & 0xF8u) == 0xF0u) {
        len = 4u;
    } else {
        return 0u;
    }

    for (i = 1u; i < len; i++) {
        const unsigned char cc = (unsigned char)s[n + i];

        if (cc == '\0' || (cc & 0xC0u) != 0x80u) {
            return 0u;
        }
    }

    return len;
}
```

